// Syscall Interface: Privileged Resource Access
#define O_WRONLY (1 << 0)
#define O_CREAT  (1 << 6)

// User process requests file access (via syscall wrapper)
int fd = open("data.txt", O_WRONLY | O_CREAT, 0644);

if (fd < 0) {
    // Kernel returned error (e.g., permission issue)
    return -1; 
}

// ECF: Signal Handler (Asynchronous Interrupt/Trap)
void sig_handler(int sig) {
    // Control flow diverted from normal execution
    if (sig == SIGSEGV) {
        // Critical exception/fault handling (Trap)
        exit(1);
    }
}

// Register handler using a syscall wrapper
struct sigaction sa = {0};
sa.sa_handler = sig_handler;
sigaction(SIGINT, &sa, NULL);
